self.KB_CONTENT["card:792084"]={"id":"card:792084","ty":"card","sourceId":"792084","title":"『出貨通知單建立作業』中的『交易條件 (TA093)』為何？","ver":"GP4以上","topic":"發票","keywords":["發票","出貨","交易"],"y":"other","answer":"* 1.一般、2.FOB、3.C&F、4.C&I、5.CIF、6.FOB&C、7.C&F&C、8.C&I&C及9.CIF&C。發票資料","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
